// filter + map + collect:
List<Integer> evensSquared = nums.stream()
    .filter(n -> n % 2 == 0)
    .map(n -> n * n)
    .toList(); // [4, 16, 36, 64]

// reduce:
int sum = nums.stream()
    .reduce(0, Integer::sum); // 36

// count + sorted:
long count = nums.stream()
    .filter(n -> n > 3)
    .sorted()
    .count(); // 5

// grouping:
Map<Boolean, List<Integer>> grouped = nums.stream()
    .collect(Collectors.partitioningBy(n -> n % 2 == 0));

